// ahb_driver.sv
class ahb_driver extends uvm_driver #(ahb_seq_item);
  `uvm_component_utils(ahb_driver)

  virtual ahb_if vif;

  // Track if DUT is in error state to handle HREADY properly
  bit in_error_response;

  function new(string name = "ahb_driver", uvm_component parent = null);
    super.new(name, parent);
    in_error_response = 0;
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(virtual ahb_if)::get(this, "", "vif", vif))
      `uvm_fatal("NOVIF", "Virtual interface not found for ahb_driver")
  endfunction

  task run_phase(uvm_phase phase);
    // Initialize signals
    vif.drv_cb.HSEL   <= 0;
    vif.drv_cb.HADDR  <= 0;
    vif.drv_cb.HWRITE <= 0;
    vif.drv_cb.HTRANS <= 2'b00;
    vif.drv_cb.HSIZE  <= 3'b010;
    vif.drv_cb.HBURST <= 3'b000;
    vif.drv_cb.HREADY <= 1;
    vif.drv_cb.HWDATA <= 0;

    // Wait for reset to de-assert
    @(posedge vif.HRESETn);
    @(vif.drv_cb);

    forever begin
      ahb_seq_item req;
      seq_item_port.get_next_item(req);
      drive_transaction(req);
      seq_item_port.item_done();
    end
  endtask

  task drive_transaction(ahb_seq_item req);
    // Wait until HREADYOUT is high (slave ready) before driving new address phase
    // If HREADYOUT is low (error response), we need to wait
    while (!vif.drv_cb.HREADYOUT) begin
      // During error response, drive IDLE on the bus and keep HREADY following HREADYOUT
      vif.drv_cb.HREADY <= vif.drv_cb.HREADYOUT;
      vif.drv_cb.HSEL   <= 0;
      vif.drv_cb.HTRANS <= 2'b00;
      @(vif.drv_cb);
    end

    // HREADYOUT is high, so HREADY should be high
    vif.drv_cb.HREADY <= 1;

    // Drive address phase signals
    vif.drv_cb.HSEL   <= req.hsel;
    vif.drv_cb.HADDR  <= req.haddr;
    vif.drv_cb.HWRITE <= req.hwrite;
    vif.drv_cb.HTRANS <= req.htrans;
    vif.drv_cb.HSIZE  <= req.hsize;
    vif.drv_cb.HBURST <= req.hburst;

    @(vif.drv_cb);

    // Drive data phase (HWDATA for the address phase we just drove)
    // HWDATA is driven in the cycle after address phase
    vif.drv_cb.HWDATA <= req.hwdata;

    // Check if error response started
    if (!vif.drv_cb.HREADYOUT) begin
      // Error response cycle 1 (HREADYOUT=0, HRESP=1)
      // Drive IDLE and set HREADY=0 to indicate we saw the wait
      vif.drv_cb.HREADY <= 0;
      vif.drv_cb.HSEL   <= 0;
      vif.drv_cb.HTRANS <= 2'b00;
      @(vif.drv_cb);
      // Error response cycle 2 (HREADYOUT=1, HRESP=1)
      vif.drv_cb.HREADY <= 1;
      @(vif.drv_cb);
    end

    `uvm_info("DRV", $sformatf("Drove: %s", req.convert2string()), UVM_HIGH)
  endtask
endclass

