// ahb_monitor.sv
class ahb_monitor extends uvm_monitor;
  `uvm_component_utils(ahb_monitor)

  virtual ahb_if vif;
  uvm_analysis_port #(ahb_seq_item) ap;

  // Pipeline registers to track address phase
  logic        prev_hsel;
  logic [31:0] prev_haddr;
  logic        prev_hwrite;
  logic [1:0]  prev_htrans;
  logic [2:0]  prev_hsize;
  logic [2:0]  prev_hburst;
  logic        prev_valid;

  function new(string name = "ahb_monitor", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap = new("ap", this);
    if (!uvm_config_db#(virtual ahb_if)::get(this, "", "vif", vif))
      `uvm_fatal("NOVIF", "Virtual interface not found for ahb_monitor")
  endfunction

  task run_phase(uvm_phase phase);
    prev_valid = 0;
    prev_hsel  = 0;
    prev_haddr = 0;
    prev_hwrite = 0;
    prev_htrans = 2'b00;
    prev_hsize  = 3'b010;
    prev_hburst = 3'b000;

    // Wait for reset de-assertion
    @(posedge vif.HRESETn);

    forever begin
      @(vif.mon_cb);
      monitor_bus();
    end
  endtask

  task monitor_bus();
    ahb_seq_item txn;

    // When HREADYOUT=1 (and HREADY=1), the data phase for the previous address is completing
    // and a new address phase is being accepted
    if (vif.mon_cb.HREADY && vif.mon_cb.HREADYOUT) begin
      // If we had a valid previous transfer, capture the completed data phase
      if (prev_valid) begin
        txn = ahb_seq_item::type_id::create("mon_txn");
        txn.hsel   = prev_hsel;
        txn.haddr  = prev_haddr;
        txn.hwrite = prev_hwrite;
        txn.htrans = prev_htrans;
        txn.hsize  = prev_hsize;
        txn.hburst = prev_hburst;
        txn.hwdata = vif.mon_cb.HWDATA;
        txn.hrdata = vif.mon_cb.HRDATA;
        txn.hreadyout = vif.mon_cb.HREADYOUT;
        txn.hresp  = vif.mon_cb.HRESP;

        `uvm_info("MON", $sformatf("Captured: %s", txn.convert2string()), UVM_HIGH)
        ap.write(txn);
      end

      // Capture current address phase for next data phase
      prev_hsel   = vif.mon_cb.HSEL;
      prev_haddr  = vif.mon_cb.HADDR;
      prev_hwrite = vif.mon_cb.HWRITE;
      prev_htrans = vif.mon_cb.HTRANS;
      prev_hsize  = vif.mon_cb.HSIZE;
      prev_hburst = vif.mon_cb.HBURST;
      prev_valid  = vif.mon_cb.HSEL &&
                    (vif.mon_cb.HTRANS == 2'b10 || vif.mon_cb.HTRANS == 2'b11);
    end
    else if (vif.mon_cb.HRESP) begin
      // Error response detected - capture error transaction
      if (prev_valid) begin
        txn = ahb_seq_item::type_id::create("mon_err_txn");
        txn.hsel   = prev_hsel;
        txn.haddr  = prev_haddr;
        txn.hwrite = prev_hwrite;
        txn.htrans = prev_htrans;
        txn.hsize  = prev_hsize;
        txn.hburst = prev_hburst;
        txn.hwdata = vif.mon_cb.HWDATA;
        txn.hrdata = vif.mon_cb.HRDATA;
        txn.hreadyout = vif.mon_cb.HREADYOUT;
        txn.hresp  = vif.mon_cb.HRESP;

        // Only send once at the end of error (HREADYOUT=1)
        if (vif.mon_cb.HREADYOUT) begin
          `uvm_info("MON", $sformatf("Error Captured: %s", txn.convert2string()), UVM_HIGH)
          ap.write(txn);
          prev_valid = 0;
        end
      end
    end
  endtask
endclass

