class ahb_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(ahb_scoreboard)

  uvm_analysis_imp #(ahb_seq_item, ahb_scoreboard) ap;

  // Reference memory model
  logic [31:0] ref_mem [32];

  int num_writes;
