  int num_errors;
  int num_matches;
  int num_mismatches;

  function new(string name = "ahb_scoreboard", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap = new("ap", this);
    // Initialize reference memory to zero (matching RTL reset)
    for (int i = 0; i < 32; i++) ref_mem[i] = 32'h0;
    num_writes = 0;
    num_reads  = 0;
    num_errors = 0;
    num_matches = 0;
    num_mismatches = 0;
  endfunction

  function void write(ahb_seq_item txn);
    logic [4:0]  word_idx;
    logic        is_valid_transfer;
    logic        size_supported;
    logic        aligned;
    logic        access_ok;
    logic [31:0] expected_rdata;
    logic [31:0] write_data;

    // Determine if this was a valid transfer
    is_valid_transfer = txn.hsel &&
                        (txn.htrans == 2'b10 || txn.htrans == 2'b11);

    if (!is_valid_transfer) return;

    // Check size support
    size_supported = (txn.hsize == 3'b000) || (txn.hsize == 3'b001) || (txn.hsize == 3'b010);

    // Check alignment
    aligned = 1'b0;
    case (txn.hsize)
      3'b000: aligned = 1'b1;                        // Byte always aligned
      3'b001: aligned = (txn.haddr[0] == 1'b0);     // Halfword
      3'b010: aligned = (txn.haddr[1:0] == 2'b00);  // Word
      default: aligned = 1'b0;
    endcase

    access_ok = size_supported && aligned;

    word_idx = txn.haddr[6:2];

    // --- Error response check ---
    if (!access_ok) begin
      num_errors++;
      if (txn.hresp !== 1'b1) begin
        `uvm_error("SB", $sformatf("Expected error response for misaligned/bad-size access HADDR=0x%08h HSIZE=%03b but got HRESP=%0b",
                   txn.haddr, txn.hsize, txn.hresp))
        num_mismatches++;
      end else begin
        `uvm_info("SB", $sformatf("Error response correctly detected for HADDR=0x%08h HSIZE=%03b",
                  txn.haddr, txn.hsize), UVM_MEDIUM)
        num_matches++;
      end
      return;
    end

    // --- Valid access ---
    // Check HRESP should be OKAY
    if (txn.hresp !== 1'b0) begin
      `uvm_error("SB", $sformatf("Valid access got HRESP=1 (error) for HADDR=0x%08h HSIZE=%03b",
                 txn.haddr, txn.hsize))
      num_mismatches++;
      return;
    end

    if (txn.hwrite) begin
      // --- WRITE ---
      num_writes++;
      write_data = ref_mem[word_idx];
      case (txn.hsize)
        3'b000: begin // Byte
          case (txn.haddr[1:0])
            2'b00: write_data[7:0]   = txn.hwdata[7:0];
            2'b01: write_data[15:8]  = txn.hwdata[7:0];
            2'b10: write_data[23:16] = txn.hwdata[7:0];
            2'b11: write_data[31:24] = txn.hwdata[7:0];
          endcase
        end
        3'b001: begin // Halfword
          case (txn.haddr[1])
            1'b0: write_data[15:0]  = txn.hwdata[15:0];
            1'b1: write_data[31:16] = txn.hwdata[15:0];
          endcase
        end
        3'b010: begin // Word
          write_data = txn.hwdata;
        end
      endcase
      ref_mem[word_idx] = write_data;
      `uvm_info("SB", $sformatf("Write: mem[%0d] = 0x%08h (addr=0x%08h size=%03b)",
                word_idx, write_data, txn.haddr, txn.hsize), UVM_HIGH)
    end else begin
      // --- READ ---
      num_reads++;
      expected_rdata = 32'h0;
      case (txn.hsize)
        3'b000: begin // Byte
          case (txn.haddr[1:0])
            2'b00: expected_rdata[7:0] = ref_mem[word_idx][7:0];
            2'b01: expected_rdata[7:0] = ref_mem[word_idx][15:8];
            2'b10: expected_rdata[7:0] = ref_mem[word_idx][23:16];
            2'b11: expected_rdata[7:0] = ref_mem[word_idx][31:24];
          endcase
        end
        3'b001: begin // Halfword
          case (txn.haddr[1])
            1'b0: expected_rdata[15:0] = ref_mem[word_idx][15:0];
            1'b1: expected_rdata[15:0] = ref_mem[word_idx][31:16];
          endcase
        end
        3'b010: begin // Word
          expected_rdata = ref_mem[word_idx];
        end
      endcase

      if (txn.hrdata === expected_rdata) begin
        num_matches++;
        `uvm_info("SB", $sformatf("Read MATCH: addr=0x%08h size=%03b expected=0x%08h actual=0x%08h",
                  txn.haddr, txn.hsize, expected_rdata, txn.hrdata), UVM_HIGH)
      end else begin
        num_mismatches++;
        `uvm_error("SB", $sformatf("Read MISMATCH: addr=0x%08h size=%03b expected=0x%08h actual=0x%08h",
                   txn.haddr, txn.hsize, expected_rdata, txn.hrdata))
      end
    end
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("SB", $sformatf("\n========== SCOREBOARD SUMMARY =========="), UVM_LOW)
    `uvm_info("SB", $sformatf("  Total Writes:     %0d", num_writes), UVM_LOW)
    `uvm_info("SB", $sformatf("  Total Reads:      %0d", num_reads), UVM_LOW)
    `uvm_info("SB", $sformatf("  Total Errors:     %0d", num_errors), UVM_LOW)
    `uvm_info("SB", $sformatf("  Matches:          %0d", num_matches), UVM_LOW)
    `uvm_info("SB", $sformatf("  Mismatches:       %0d", num_mismatches), UVM_LOW)
    `uvm_info("SB", $sformatf("============================================"), UVM_LOW)
    if (num_mismatches > 0)
      `uvm_error("SB", $sformatf("TEST FAILED: %0d mismatches detected!", num_mismatches))
    else
      `uvm_info("SB", "TEST PASSED: All checks matched!", UVM_LOW)
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Functional Coverage (uvm_subscriber)
// ════════════════════════════════════════════════════════════

// ahb_coverage.sv
class ahb_coverage extends uvm_subscriber #(ahb_seq_item);
  `uvm_component_utils(ahb_coverage)

  ahb_seq_item txn;

  covergroup ahb_cg;
    // Transfer type
    cp_htrans: coverpoint txn.htrans {
      bins idle   = {2'b00};
      bins nonseq = {2'b10};
      bins seq    = {2'b11};
    }

    // Transfer direction
    cp_hwrite: coverpoint txn.hwrite {
      bins read  = {0};
      bins write = {1};
    }

    // Transfer size
    cp_hsize: coverpoint txn.hsize {
      bins byte_size = {3'b000};
      bins half_size = {3'b001};
      bins word_size = {3'b010};
      bins unsupported[] = {[3'b011:3'b111]};
    }

    // HSEL
    cp_hsel: coverpoint txn.hsel {
      bins deselected = {0};
      bins selected   = {1};
    }

    // Response
    cp_hresp: coverpoint txn.hresp {
      bins okay  = {0};
      bins error = {1};
    }

    // HREADYOUT
    cp_hreadyout: coverpoint txn.hreadyout {
      bins ready    = {1};
      bins not_ready = {0};
    }

    // Word address index (5 bits)
    cp_word_idx: coverpoint txn.haddr[6:2] {
      bins word_addr[] = {[0:31]};
    }

    // Byte lane
    cp_byte_lane: coverpoint txn.haddr[1:0] {
      bins lane[] = {[0:3]};
    }

    // Alignment scenarios
    cp_alignment: coverpoint {txn.hsize, txn.haddr[1:0]} {
      bins byte_at_0  = {5'b000_00};
      bins byte_at_1  = {5'b000_01};
      bins byte_at_2  = {5'b000_10};
      bins byte_at_3  = {5'b000_11};
      bins half_at_0  = {5'b001_00};
      bins half_at_2  = {5'b001_10};
      bins half_misaligned_1 = {5'b001_01};
      bins half_misaligned_3 = {5'b001_11};
      bins word_at_0  = {5'b010_00};
      bins word_misaligned_1 = {5'b010_01};
      bins word_misaligned_2 = {5'b010_10};
      bins word_misaligned_3 = {5'b010_11};
    }

    // Cross coverage: direction × size
    cx_write_size: cross cp_hwrite, cp_hsize {
      ignore_bins unsup_write = binsof(cp_hsize.unsupported);
    }

    // Cross coverage: direction × response
    cx_write_resp: cross cp_hwrite, cp_hresp;

    // Cross coverage: htrans × hsel
    cx_trans_sel: cross cp_htrans, cp_hsel;

    // Cross coverage: size × response
    cx_size_resp: cross cp_hsize, cp_hresp;

    // Cross coverage: size × byte_lane for read
    cx_size_lane_read: cross cp_hsize, cp_byte_lane, cp_hwrite {
      ignore_bins writes = binsof(cp_hwrite.write);
      ignore_bins unsup = binsof(cp_hsize.unsupported);
    }
  endgroup

  function new(string name = "ahb_coverage", uvm_component parent = null);
    super.new(name, parent);
    ahb_cg = new();
  endfunction

  function void write(ahb_seq_item t);
    txn = t;
    ahb_cg.sample();
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("COV", $sformatf("Functional Coverage: %.2f%%", ahb_cg.get_coverage()), UVM_LOW)
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Agent (uvm_agent)
// ════════════════════════════════════════════════════════════

// ahb_agent.sv
class ahb_agent extends uvm_agent;
  `uvm_component_utils(ahb_agent)

  ahb_sequencer sqr;
  ahb_driver    drv;
  ahb_monitor   mon;

  uvm_analysis_port #(ahb_seq_item) ap;

  function new(string name = "ahb_agent", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    mon = ahb_monitor::type_id::create("mon", this);
    ap  = new("ap", this);

    if (get_is_active() == UVM_ACTIVE) begin
      sqr = ahb_sequencer::type_id::create("sqr", this);
      drv = ahb_driver::type_id::create("drv", this);
    end
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    mon.ap.connect(ap);

    if (get_is_active() == UVM_ACTIVE) begin
      drv.seq_item_port.connect(sqr.seq_item_export);
    end
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Environment (uvm_env)
// ════════════════════════════════════════════════════════════

// ahb_env.sv
class ahb_env extends uvm_env;
  `uvm_component_utils(ahb_env)

  ahb_agent      agent;
  ahb_scoreboard sb;
  ahb_coverage   cov;

  function new(string name = "ahb_env", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    agent = ahb_agent::type_id::create("agent", this);
    sb    = ahb_scoreboard::type_id::create("sb", this);
    cov   = ahb_coverage::type_id::create("cov", this);
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    agent.ap.connect(sb.ap);
    agent.ap.connect(cov.analysis_export);
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Test (uvm_test)
// ════════════════════════════════════════════════════════════

// ahb_test.sv
class ahb_base_test extends uvm_test;
  `uvm_component_utils(ahb_base_test)

  ahb_env env;

  function new(string name = "ahb_base_test", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    env = ahb_env::type_id::create("env", this);
  endfunction

  task run_phase(uvm_phase phase);
    ahb_master_seq master_seq;

    phase.raise_objection(this, "Starting ahb_base_test");

    // Wait for reset to complete
    #100;

    master_seq = ahb_master_seq::type_id::create("master_seq");
    master_seq.start(env.agent.sqr);

    // Allow time for final transactions to propagate
    #200;

    phase.drop_objection(this, "Finished ahb_base_test");
  endtask

  function void report_phase(uvm_phase phase);
    uvm_report_server svr;
    super.report_phase(phase);
    svr = uvm_report_server::get_server();
    if (svr.get_severity_count(UVM_ERROR) == 0 &&
        svr.get_severity_count(UVM_FATAL) == 0)
      `uvm_info("TEST", "========== TEST PASSED ==========", UVM_NONE)
    else
      `uvm_info("TEST", "========== TEST FAILED ==========", UVM_NONE)
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// UVM Top (tb_top)
// ════════════════════════════════════════════════════════════

module tb_top;

  // Clock generation
  logic HCLK;
  initial begin
    HCLK = 0;
    forever #5 HCLK = ~HCLK; // 100 MHz clock
  end

  // Interface instantiation
  ahb_if ahb_vif(.HCLK(HCLK));

  // DUT instantiation
  ahb_mem u_dut (
    .HRESETn   (ahb_vif.HRESETn),
    .HCLK      (HCLK),
    .HSEL      (ahb_vif.HSEL),
    .HADDR     (ahb_vif.HADDR),
    .HWRITE    (ahb_vif.HWRITE),
    .HTRANS    (ahb_vif.HTRANS),
    .HSIZE     (ahb_vif.HSIZE),
    .HBURST    (ahb_vif.HBURST),
    .HREADY    (ahb_vif.HREADY),
    .HWDATA    (ahb_vif.HWDATA),
    .HRDATA    (ahb_vif.HRDATA),
    .HREADYOUT (ahb_vif.HREADYOUT),
    .HRESP     (ahb_vif.HRESP)
  );

  // Reset generation
  initial begin
    ahb_vif.HRESETn = 0;
    // Initialize bus signals during reset
    ahb_vif.HSEL   = 0;
    ahb_vif.HADDR  = 0;
    ahb_vif.HWRITE = 0;
    ahb_vif.HTRANS = 2'b00;
    ahb_vif.HSIZE  = 3'b010;
    ahb_vif.HBURST = 3'b000;
    ahb_vif.HREADY = 1;
    ahb_vif.HWDATA = 0;

    repeat (10) @(posedge HCLK);
    ahb_vif.HRESETn = 1;
    `uvm_info("TB_TOP", "Reset de-asserted", UVM_MEDIUM)
  end

  // Store virtual interface in config_db and start test
  initial begin
    uvm_config_db#(virtual ahb_if)::set(null, "*", "vif", ahb_vif);
    run_test("ahb_base_test");
  end

  // Waveform dump
  initial begin
    $dumpfile("ahb_dump.vcd");
    $dumpvars(0, tb_top);
  end

  // Simulation timeout
  initial begin
    #1000000;
    `uvm_fatal("TIMEOUT", "Simulation timed out!")
  end
endmodule

